import numpy as np, csv, itertools, collections
rows=list(csv.DictReader(open('log.csv')))
knobs=['lr_scale','warmup','micro_bs','grad_accum','zero_stage','seq_len','act_ckpt','dropout','opt_eps']
hw=['nccl_bw_gbps','sm_clock_mhz']
X={k:np.array([float(r[k]) for r in rows]) for k in knobs+['offload']+hw+['grad_norm_p95','throughput_toks_s','step_time_ms','val_loss']}
y=X['val_loss']; n=len(y)
def dummies(k):
    vals=sorted(set(X[k])); return [(f'{k}={v}',(X[k]==v).astype(float)) for v in vals[1:]]
def design(terms):
    cols=[('1',np.ones(n))]
    for t in terms:
        if isinstance(t,str): cols+=dummies(t)
        else:
            a,b=t
            for na,ca in dummies(a):
                for nb,cb in dummies(b): cols.append((na+'*'+nb,ca*cb))
    return [c[0] for c in cols], np.column_stack([c[1] for c in cols])
def fit(terms):
    names,A=design(terms); beta,res,rk,sv=np.linalg.lstsq(A,y,rcond=None)
    r=y-A@beta; rss=r@r; return names,beta,rss,A.shape[1]
base=knobs+hw
names,beta,rss0,p0=fit(base)
print('additive knobs+hw: rss',rss0,'sigma',np.sqrt(rss0/(n-p0)))
for nm,b in zip(names,beta): print(f'  {nm:30s} {b:+.4f}')
# hw generation only?
gen=(X['nccl_bw_gbps']>150).astype(float)
# test each pairwise interaction
print('\npairwise interactions F-test-ish (delta rss, df):')
allf=knobs+hw
res=[]
for a,b in itertools.combinations(allf,2):
    names1,beta1,rss1,p1=fit(base+[(a,b)])
    df=p1-p0; F=((rss0-rss1)/df)/(rss1/(n-p1))
    res.append((F,a,b,df,rss0-rss1))
for F,a,b,df,d in sorted(res,reverse=True)[:20]: print(f'  {a:12s} {b:12s} F={F:8.2f} df={df} drss={d:.4f}')
